"""Printed 291–292: separation, homogeneous definitions, examples 7–8."""
import math
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path

def family():
 def pt(x,y):return(210+78*x,330-28*y)
 paths=[path([pt(-2.2,0),pt(2.7,0)]),path([pt(0,-1),pt(0,10.8)])];labels=[(426,337,'x'),(206,20,'y'),(190,350,'O')]
 for c in [1,2,3]:
  pts=[]
  for i in range(-200,251,3):
   x=i/100;y=c*math.exp(x)
   if y<=10.4:pts.append(pt(x,y))
  paths.append(path(pts,stroke='#b91c1c'));xx,yy=pts[-1];labels.append((xx+4,yy+5,'c₁='+str(c)))
 for x in [-2,-1,1,2]:
  xx,yy=pt(x,0);paths.append(path([(xx,yy-4),(xx,yy+4)]));labels.append((xx-4,yy+23,str(x)))
 for y in range(1,11):
  xx,yy=pt(0,y);paths.append(path([(xx-4,yy),(xx+4,yy)]));labels.append((xx-22,yy+5,str(y)))
 x,y=pt(1,1);paths.append(path([(x,y),(x,y-84)],dash=True));labels.append((x+7,y-43,'same x'))
 return geometry('Figure 10.2','Figure 10.2 — exponential solution family y=c₁e^x, plotted sample positive constants c₁=1,2,3',paths,labels,size=(480,375))
SEPARABLE=[heading('10.3 Solution of differential equations'),paragraph('If the solution of a first order differential equation is not possible by direct integration, then, the integral process (in case of difficulties) for obtaining the solution of a differential equation indicates the actual concept of a differential equation.'),heading('10.3.1 Solution of first order and first degree differential equations'),paragraph('We examine techniques for solving first order differential equations. For this unit, the recommended techniques for solving the differential equations are the separation of variables, reducible to separation form, homogeneous and equations reducible to homogeneous form.'),heading('i. Separable variables'),paragraph('If the solution of a differential equation is not possible by direct integration, then the integral technique called separation of variables will be used for solving the differential equation. Separation of variables is a technique commonly used to solve first order differential equations. It is so called because we try to rearrange the equation to be solved in such a way that all terms involving the dependent variable (y say) appear on one side of the equation, and all terms involving the independent variable (x say) appear on the other side. It is not possible to rearrange all first order differential equations in this way so this technique is not always appropriate. Further, it is not always possible to perform the integration even if the variables are separable.'),paragraph('In general, a differential equation of the form:'),eq(r'\frac{dy}{dx}=\frac{f(x)}{g(y)},\quad g(y)\ne0','i'),paragraph('By shifting x on one side and y on the other side:'),eq(r'g(y)\,dy=f(x)\,dx,\quad\mathrm{SDE}','ii'),paragraph('This gives a separable differential equation. Its solution can be found by integrating the left side w.r.t. y and the right side w.r.t. x.'),heading('Example 7'),paragraph('Find the general solution of the linear differential equation dy/dx=y.'),heading('Solution'),paragraph('The solution of the given differential equation is not possible by direct integration. The separable form of the given first order differential equation is obtained by shifting y on the left and x on the right:'),eq(r'\frac{1}{y}\,dy=dx'),paragraph('Integrating both sides:'),eq(r'\int\frac{1}{y}\,dy=\int dx\quad\Rightarrow\quad\ln y=x+c'),eq(r'y=e^{x+c}=e^xe^c=c_1e^x,\quad c_1=e^c'),paragraph('This gives the general solution depending on a single arbitrary constant c. This general solution represents a family of exponential functions as shown in Figure 10.2.'),family(),heading('Remember'),paragraph('If the solution of the differential equation is not possible by separable form, then the given differential equation can be reduced in separable form by substitution. This substitution changes the dependent variable for a new variable, say u, and keeps x as the independent variable.'),note('For y′=y, dividing by y omits the equilibrium y=0. Use ln|y| for nonzero real branches, giving y=Ce^x with any real C, including zero; the source e^c parametrizes only positive C. Figure 10.2 displays sample positive members, not every solution. Some equations permit useful substitutions, but the Remember statement is not a guarantee for every first-order equation. Separation may produce valid implicit integrals even when no elementary antiderivative exists; preserve original denominator restrictions.')]
REDUCIBLE=[heading('Example 8'),paragraph('Find the general solution of the non-linear differential equation dy/dx=(x+y)².'),heading('Solution'),paragraph('The given non-linear differential equation is not separable but can be reduced into separable form by substitution: x+y=u(x). Differentiating w.r.t. x gives:'),eq(r'\frac{d}{dx}(x+y)=\frac{dx}{dx}+\frac{dy}{dx}=1+\frac{dy}{dx}=\frac{du}{dx}\quad\Rightarrow\quad\frac{dy}{dx}=\frac{du}{dx}-1'),paragraph('Use x+y=u and dy/dx=du/dx−1 in the original differential equation:'),eq(r'\frac{du}{dx}-1=u^2\quad\Rightarrow\quad\frac{du}{dx}=1+u^2\quad\Rightarrow\quad\frac{du}{1+u^2}=dx','i'),paragraph('Integrating to obtain the general solution:'),eq(r'\int\frac{du}{1+u^2}=\int dx\quad\Rightarrow\quad\tan^{-1}u=x+c\quad\Rightarrow\quad u=\tan(x+c)'),paragraph('Back substitution of u=x+y gives:'),eq(r'x+y=\tan(x+c)\quad\Rightarrow\quad y=-x+\tan(x+c)'),paragraph('This is the general solution of the given differential equation depending on a single arbitrary constant c.'),note('Take real solution intervals avoiding tan poles, cos(x+c)=0. Differentiation gives y′=−1+sec²(x+c)=tan²(x+c)=(x+y)². Since 1+u²>0 for real u, this separation loses no real equilibrium solutions. The arctangent equation is local to a branch; constants differing by π give the same tangent function.')]
HOMOGENEOUS=[heading('ii. Homogeneous equations'),paragraph('The homogeneous differential equations are related to homogeneous functions.'),paragraph('A function f(x,y) is homogeneous function of degree n in variables x and y if and only if for all values of the variables x,y and for every positive value of λ, the identity is true:'),eq(r'f(\lambda x,\lambda y)=\lambda^n f(x,y),\quad n=1,2,3,\ldots','i'),paragraph('For illustration f(x,y)=x²+y² is homogeneous of degree 2 since:'),eq(r'f(\lambda x,\lambda y)=(\lambda x)^2+(\lambda y)^2=\lambda^2(x^2+y^2)=\lambda^2f(x,y)'),paragraph('The identity is not true for f(x,y)=x²+y²+1, since the function is not homogeneous.'),eq(r'\frac{dy}{dx}=\frac{f(x,y)}{g(x,y)}','ii'),paragraph('The differential equation is called a homogeneous differential equation, if it defines a homogeneous function of degree zero. It can be reduced to separable form by introducing a new variable:'),eq(r'u(x)=\frac{y}{x}\quad\mathrm{or}\quad y=ux,\quad\frac{dy}{dx}=\frac{d}{dx}(ux)=u+x\frac{du}{dx}','iii'),paragraph('Substitution of (iii) in equation (ii) automatically converts the homogeneous differential equation into a separable differential equation.'),note('The ratio f/g must have degree zero where defined, for example when f and g have the same degree and g≠0. Homogeneous functions can have degree zero or other real degrees on suitable scaling domains; the printed n=1,2,3,… is an illustrative restriction. On x≠0, write y′=F(y/x) locally and substitute u=y/x to obtain x u′=F(u)−u. Before dividing by F(u)−u, keep constant-u solutions F(u)=u; they represent straight-line solutions y=ux. Positive scaling alone may leave distinct x>0 and x<0 branches.')]
PAGES=[page('150_page_1.jpg',291,SEPARABLE),page('150_page_2.jpg',292,REDUCIBLE+HOMOGENEOUS)]
for p in PAGES:p.update(title='DIFFERENTIAL EQUATIONS',visualStatus='Complete separation formulas, native exponential family and homogeneous substitution proof',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':150,'side':'left' if p['page']==291 else 'right','reason':'All separation denominators, substitution derivatives, exponentials and homogeneity identities visually checked'})
EXAMPLES=[]
for n,q,steps,ans,pg in [
('7','Find the general solution of y′=y.',['First retain the equilibrium solution y=0.','For a nonzero solution, separate dy/y=dx.','Integrate: ln|y|=x+C on an interval where y has constant sign.','Exponentiate with that sign retained: y=Ae^x for any nonzero real A.','Include A=0 to recover the equilibrium; this single family describes all real solutions.','Check y′=Ae^x=y. The graph illustrates A=1,2,3 only; negative constants give negative solution curves.'],'y=Ae^x, A∈ℝ.',291),
('8','Find the general solution of y′=(x+y)².',['Set u=x+y, keeping x as the independent variable.','Differentiate: u′=1+y′, so y′=u′−1.','Substitute in the original equation: u′−1=u², hence u′=1+u².','Separate du/(1+u²)=dx; its denominator is strictly positive for real u.','Integrate: arctan u=x+C locally, hence u=tan(x+C).','Back substitute: y=tan(x+C)−x on intervals avoiding poles where cos(x+C)=0.','Verify y′=sec²(x+C)−1=tan²(x+C) and (x+y)²=tan²(x+C).'],'y=tan(x+C)−x, on intervals without tangent poles.',292)]:
 EXAMPLES.append({'num':n,'title':'Separable and Reducible Equations','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':pg,'jpg':'150_page_'+str(1 if pg==291 else 2)+'.jpg','verification':'Source integration, arbitrary constant and substitution checked'}]})
